package com.gitgalaxy.modernized.batch;

import com.gitgalaxy.modernized.service.Cbact02cService;
import java.util.List;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;

/** JCL job READCARD (app/jcl/READCARD.jcl) as a Spring Batch job (#3622): its steps in JCL order,
 *  each bypassed when its COND= (or the job's) is satisfied, as JCL does.
 *  JCL job flow field testing: open (5 public / 0 private estates). */
@Configuration
public class ReadcardJobConfig {

    static final List<Dd> DDS_STEP05 = List.of(new Dd("STEPLIB", "AWS.M2.CARDDEMO.LOADLIB", "SHR", null, null), new Dd("CARDFILE", "AWS.M2.CARDDEMO.CARDDATA.VSAM.KSDS", "SHR", null, null));

    @Bean
    public Job readcardJob(JobRepository jobRepository, PlatformTransactionManager tx, JclSteps steps, Cbact02cService cbact02cService) {
        return new JobBuilder("READCARD", jobRepository)
                .start(new StepBuilder("STEP05", jobRepository)
                        .tasklet(steps.program("STEP05", "STEP05", null, null, null, () -> cbact02cService.runBatch(DDS_STEP05, null)), tx).build())
                .build();
    }
}
